const DESCRIPTIONS = {"Six qui prend": {"fr": "Posez vos cartes en évitant d'être le sixième dans une rangée, sinon vous ramassez les têtes de bœuf ! Un jeu de cartes malin qui se joue à plein.", "en": "Play number cards in growing rows, but whoever puts down the sixth card has to take the whole row! A clever, slightly mean family card game."}, "Suspect": {"fr": "Un jeu d'enquête en équipe: on pose des questions pour deviner le coupable parmi les suspects. Idéal pour jouer les petits détectives en famille.", "en": "Question witnesses and use clues to figure out who did it. A friendly mini investigation game perfect for budding detectives."}, "Azul": {"fr": "Un magnifique jeu de pose de tuiles où l'on décore un palais portugais avec des azulejos colorés. Simple à apprendre, super malin à jouer.", "en": "Place beautiful Portuguese tiles to decorate the royal palace walls in this colorful pattern-building game where smart choices score the most points."}, "Similo": {"fr": "Jeu coopératif de cartes où il faut faire deviner un personnage caché grâce à des indices visuels. Astucieux, original et très joli !", "en": "A cooperative card game where one player gives picture-card clues so the others can guess a secret character. Tricky, since clues can mean similar OR different!"}, "Pickomino": {"fr": "Un jeu de dés gourmand où l'on chipe des brochettes de vers à ses adversaires. Faut-il pousser sa chance ou s'arrêter ? Tendu et rigolo.", "en": "Roll dice and grab grilled-worm tiles for your chickens in this fun push-your-luck game where you weigh greed against caution."}, "Hanabi": {"fr": "Un jeu coopératif où chacun voit les cartes des autres mais pas les siennes. Ensemble, on essaie de réussir un magnifique feu d'artifice.", "en": "A cooperative card game where you build dazzling fireworks together, but can only see other players' cards, not your own. Clever, friendly, brain-tickling."}, "Next!": {"fr": "Un petit jeu d'observation et de rapidité où il faut enchaîner les cartes le plus vite possible. Parties courtes et nerveuses.", "en": "A speedy reaction card game where you must shout 'Next!' when the right card appears. Short, snappy, and full of giggles."}, "Skyjo": {"fr": "Un jeu de cartes malin où il faut faire le moins de points possible en retournant ses cartes au bon moment. Rapide et plein de rebondissements!", "en": "Flip and swap number cards to keep your score as low as possible. A quick, addictive card game perfect for the whole family."}, "Red 7": {"fr": "Un jeu de cartes ultra rapide où la règle change à chaque tour selon la couleur en jeu. Il faut toujours être en tête à la fin de son tour, sinon on est éliminé !", "en": "A fast filler card game where the rules keep changing — you must be winning at the end of every turn or you're out."}, "Kompromat": {"fr": "Un duel de bluff et de manipulation entre deux espions qui essaient de coincer l'autre. Tendu, malin, plutôt pour les plus grands.", "en": "A two-player bluffing card game of spies and secrets. Outwit your opponent by gathering info while hiding your own moves."}, "Révolution": {"fr": "Un jeu de stratégie où l'on tente de prendre le contrôle d'une ville en achetant l'influence des personnages avec de l'or, des bottes ou des secrets.", "en": "A bidding and bluffing game where you secretly spend influence to win over key figures and take control of the city."}, "Rolling Realms": {"fr": "Lancez des dés et remplissez plusieurs petits royaumes en parallèle : un jeu malin où chaque dé peut servir à plein de choses différentes.", "en": "A roll-and-write game where you use dice across mini-realms, each one a tiny puzzle, to score the most stars over three rounds."}, "Exploding Kittens": {"fr": "Un jeu de cartes complètement déjanté: on pioche en espérant éviter le chaton qui explose! Bourré d'humour et de coups bas, idéal entre copains.", "en": "Draw cards and pray you don't get the kitten that goes BOOM. A silly card game with cute illustrations and lots of laughs."}, "Code Names": {"fr": "Jeu d'équipes où le maître-espion donne un indice en un seul mot pour faire deviner plusieurs cartes à ses coéquipiers. Malin et palpitant.", "en": "Two teams race to find their secret agents using one-word clues. Clever hints win the day, but watch out for the assassin!"}, "Astérix": {"fr": "Plongez dans le village gaulois avec Astérix et Obélix pour un jeu de plateau plein d'aventures, de potion magique et de Romains à bousculer.", "en": "Adventures with Astérix and Obélix in a board game full of Gaulish fun, where you travel through villages and outwit Romans along the way."}, "Isle of Skye": {"fr": "On achète et vend des tuiles pour construire son petit royaume écossais. Un jeu de plateau malin où il faut bien fixer ses prix.", "en": "A tile-laying game where you build your own Scottish island while buying and selling tiles with rivals. Clever, quick, and rewarding."}, "Romi Rami": {"fr": "Un jeu de tuiles à combiner en suites et en familles, façon rami : posez, déplacez, réorganisez le tapis pour vider votre chevalet en premier.", "en": "A French card game similar to Rummy, where you make sets and sequences to be the first to empty your hand."}, "Push": {"fr": "Jeu de stop-ou-encore avec des cartes : on pousse sa chance pour accumuler des points, mais attention à ne pas tout perdre d'un coup !", "en": "A push-your-luck card game where you keep flipping cards hoping not to bust. Simple rules, big tension, perfect filler."}, "The Mind": {"fr": "Un jeu coopératif étonnant où il faut poser ses cartes dans l'ordre croissant... sans jamais se parler! Tout se joue à la connexion entre joueurs.", "en": "Play your number cards in order without speaking a single word. A magical game of intuition and shared focus."}, "Tea for 2": {"fr": "Un duel autour d'une partie de thé: on joue des cartes pour gagner des manches comme dans Alice au Pays des Merveilles. Fin et malin, à deux uniquement.", "en": "A two-player card duel set around an Alice-in-Wonderland tea party. Play cards to win rounds in this clever, light-touch face-off."}, "Canal Rush": {"fr": "Jeu de plateau où chacun construit son canal en posant des tuiles pour relier les mers et marquer un maximum de points. Stratégique et fluide.", "en": "Dig canals across the map and ship goods to score. A clever placement game where one route can boost or block another."}, "Harry Potter: Hogwarts Battle": {"fr": "Un jeu coopératif de deck-building : tous ensemble, on défend Poudlard contre les méchants au fil de plusieurs aventures, livre après livre.", "en": "A cooperative deck-building game where you team up as Harry, Ron, Hermione, and Neville to defeat dark villains across the seven books."}, "Patchwork": {"fr": "Un duel cousu main : assemblez des pièces de tissu pour former le plus beau couvre-lit. Un puzzle malin pour deux joueurs.", "en": "A two-player puzzle game where you stitch together a quilt from oddly shaped pieces, balancing time, buttons and clever placement."}, "Trio": {"fr": "Jeu de cartes futé : on cherche à révéler trois cartes identiques en fouillant dans sa main, celle des autres, ou au centre. Court et malicieux.", "en": "Hunt for matching trios by flipping cards or peeking at hands. Quick memory and bluff moments make every reveal exciting."}, "Gift Trap": {"fr": "Jeu d'ambiance où il faut deviner quel cadeau ferait plaisir à chaque joueur. Idéal pour rigoler entre amis qui se connaissent bien.", "en": "A party game where you try to guess which oddball gifts your friends would actually want. Hilarious and revealing for groups."}, "Jaipur": {"fr": "Un duel de marchands aux Indes : on échange des marchandises, on revend au bon moment et on essaie de devenir le commerçant préféré du maharadja.", "en": "A two-player trading card game set in an Indian market. Swap goods, sell at the right moment, and become the maharaja's favorite merchant."}, "Mille bornes": {"fr": "Le grand classique des jeux de cartes ! On enchaîne les kilomètres en évitant les pannes et crevaisons pour finir la course en premier.", "en": "The classic French card game of road trip racing. Play distance cards, dodge flat tires and speed limits, and be first to reach 1000 miles!"}, "Triomino": {"fr": "Comme les dominos mais en triangles ! On pose ses tuiles bout à bout en faisant correspondre les chiffres pour marquer des points.", "en": "Like dominoes, but with triangles and numbers on three sides. Match edges to score points and build a colorful tabletop tangle."}, "La Vegas": {"fr": "Lancez vos dés sur les casinos pour rafler le plus de billets ! Un jeu de dés rigolo où il faut choisir ses risques avec malice.", "en": "Roll your dice and place them on casinos to grab the biggest stacks of cash. A fun push-your-luck dice game where the most dice don't always win!"}, "Alice de l'autre côté du miroir": {"fr": "Suivez Alice dans un univers loufoque inspiré de Lewis Carroll, un jeu de plateau plein de surprises et de personnages étranges.", "en": "Step through the looking glass with Alice in a whimsical adventure game inspired by Lewis Carroll's curious wonderland."}, "Red Panda": {"fr": "Un mignon jeu familial autour des pandas roux où l'on récolte des bambous et grimpe dans les arbres. Coloré et facile à prendre en main.", "en": "A cute, family-friendly game starring adorable red pandas, with simple rules perfect for younger players."}, "Bang! Duel": {"fr": "Duel de cow-boys en cartes : un shérif contre un hors-la-loi, chacun dégaine ses coups, ses esquives et ses ruses pour l'emporter.", "en": "A two-player Wild West showdown using cards as bullets, dodges, and tricks. Outwit your rival in a fast, tense duel."}, "Perudo": {"fr": "Le célèbre jeu de dés et de bluff des pirates : annoncez combien de dés vous pensez voir sur la table… ou démasquez le menteur !", "en": "A bluffing dice game from the Andes where players hide their dice and bet on how many of each value are on the table — bluff or call!"}, "Renard des bois duo": {"fr": "La version deux joueurs du fameux jeu coopératif : ensemble, traversez la forêt et démasquez le renard avant qu'il ne s'enfuie avec le trésor.", "en": "A two-player version of The Fox in the Forest, a tricky card game where you take tricks but not too many to win."}, "The Crew": {"fr": "Un jeu de plis coopératif: l'équipage doit remplir des missions spatiales sans pouvoir trop se parler. Inventif et plein de défis!", "en": "Work together to complete tricky missions in space, one trick at a time. A cooperative card game where you can barely talk to your teammates."}, "Shatten Totten": {"fr": "Duel de cartes pour deux joueurs : capturez les bornes en formant les meilleures combinaisons. Tactique, court et très intense !", "en": "A two-player card duel where you fight for nine stones by building the strongest little poker-style hands on each side. Sharp and tactical!"}, "Dream Home": {"fr": "On meuble et on décore la maison de ses rêves en piochant des cartes pièces et objets. Un jeu mignon et stratégique pour les apprentis architectes.", "en": "Draft cards to furnish the cosiest house, room by room. Collect matching furniture and decorations to win the dream home contest."}, "Welcome to the World": {"fr": "On dessine sa ville idéale en cochant des cases sur sa feuille, selon les cartes révélées. Un jeu où tout le monde joue en même temps, simple et addictif.", "en": "Build cities around the globe by writing numbers on your sheet. A relaxing roll-and-write adventure across famous landmarks."}, "Kingdomino Duel": {"fr": "La version duel de Kingdomino avec des dés et une feuille : on dessine son royaume case par case en choisissant bien ses tuiles.", "en": "A two-player roll-and-write twist on Kingdomino using dice. Draft results, draw your kingdom on paper, and score the biggest realms."}, "Welcome": {"fr": "Bienvenue dans l'Amérique des années 50: on construit son quartier en numérotant les maisons sur sa feuille. Tout le monde joue en même temps, plein à plein!", "en": "Plan a perfect 1950s neighborhood by filling houses with numbers. A clever flip-and-write where everyone plays at the same time."}, "One Piece Nakama": {"fr": "Embarquez avec Luffy et l'équipage du Chapeau de Paille dans un jeu de cartes inspiré du manga One Piece. Pour les fans de pirates et d'aventures.", "en": "A card game set in the One Piece universe, where you gather your crew of pirates and battle rivals on the high seas."}, "Avant/Après": {"fr": "Un jeu de cartes futé où il faut deviner si un événement s'est passé avant ou après un autre. Parfait pour apprendre l'histoire en s'amusant.", "en": "A party card game where you guess what happened before or after a famous event, mixing history, pop culture and laughs."}, "Cat Lady": {"fr": "Jeu de cartes adorable où l'on collectionne des chats, on les nourrit et on évite les chats perdus. Mignon et accessible.", "en": "Draft cards to feed, collect, and pamper as many cats as possible. Cute, cozy, and full of purr-fect combos."}, "Pina Pirata": {"fr": "Un petit jeu de cartes malin où il faut se débarrasser de ses cartes avant les autres pirates, en posant des combinaisons rusées.", "en": "A pirate-themed card game where you race to empty your hand by playing matching cards. Quick, cheeky fun for the whole family."}, "Dixit": {"fr": "Un joli jeu de cartes illustrées où il faut deviner laquelle correspond à la phrase mystérieuse du conteur. Poétique, créatif et magique à tout âge.", "en": "Give a dreamy clue about your picture card and hope friends can guess it. A beautiful game of imagination and storytelling."}, "Mille Sabords!": {"fr": "Lancez les dés comme un vrai pirate pour amasser pièces, diamants et perroquets, mais attention aux têtes de mort ! Un jeu de dés palpitant.", "en": "Roll the pirate dice and push your luck for treasure, but watch out for skulls! A swashbuckling dice game where greedy buccaneers can lose it all."}, "Explorers": {"fr": "Un jeu de cartes où chacun trace son chemin d'exploration sur une feuille pour marquer le plus de points. Jeu de roll-and-write malin et accessible.", "en": "Draw paths on your map to discover treasures, mountains and villages. A speedy flip-and-write full of choices and exploration."}, "A la lettre!": {"fr": "Un jeu de mots rapide où il faut trouver des réponses commençant par une lettre imposée. Idéal en famille pour rigoler et faire chauffer les méninges.", "en": "A fast word game where you have to find answers starting with a given letter. Great for laughs and warming up the brain with the whole family."}, "Jamaica": {"fr": "Une course de pirates autour de l'île : on lance les dés, on charge son bateau de trésors et on canonne ses adversaires pour finir premier.", "en": "A pirate racing board game where you sail around the island, gather treasure, and battle rivals. Easy to learn, with surprises every turn."}, "Code Names Duo": {"fr": "La version à deux de Code Names : on coopère pour faire deviner tous les bons mots avant la fin des manches. Tendu et complice.", "en": "The cooperative version of Codenames for two players. Team up, give smart clues, and find all the agents before time runs out."}, "Nagaraja": {"fr": "Deux explorateurs fouillent un temple indien rempli de trésors et de pièges. Un duel malin de pose de baguettes et de bluff.", "en": "A two-player bluffing and tile-drafting game set in an Indian temple. Use sticks to predict each round and snatch the best treasures."}, "Lobo 77": {"fr": "Jeu de cartes rapide où l'on additionne les chiffres sans dépasser 77, sinon on perd une vie. Court, malin et plein de suspense !", "en": "A quick card game where you add numbers and try not to push the total past 77. Get caught and you lose a chip!"}, "Sky Team": {"fr": "Un jeu coopératif à deux où l'on pilote un avion en plaçant ses dés pour réussir l'atterrissage. Tendu, palpitant, et il faut bien se concerter!", "en": "Team up as pilot and co-pilot to land a plane safely. A cooperative dice game full of teamwork and quiet communication."}, "Rummikub": {"fr": "Un grand classique où l'on aligne des tuiles chiffrées en suites ou en séries. Réfléchi, tactique, et terriblement addictif en famille.", "en": "Mix and match numbered tiles into runs and sets, rearranging the table to get rid of your tiles first in this classic family game."}, "Flamme Rouge": {"fr": "Une course cycliste sur plateau : on gère ses cartes d'énergie, on prend l'aspiration du peloton et on attaque au bon moment pour gagner l'étape.", "en": "A cycling race board game where you manage your riders' energy cards over a winding course. Strategic, tense, and surprisingly thrilling."}, "Check List": {"fr": "Jeu d'ambiance où il faut placer un mot sur une échelle de 1 à 10 et deviner où les autres le mettront. Drôle et bavard.", "en": "Guess words by checking which letters they share with secret answers. A fast, brainy deduction party game."}, "Salade Points": {"fr": "Jeu de cartes où l'on collectionne des légumes pour marquer des points selon des règles rigolotes. Rapide, malin et un peu tordu !", "en": "A clever card game where fruit and veggie cards each score a different way. Pick the best combos to build the tastiest salad of points!"}, "Kingdomino": {"fr": "On pioche des tuiles type domino pour agrandir son petit royaume. Simple, rapide et toujours malin : un favori des familles.", "en": "Place domino-shaped tiles to build your own little kingdom of fields, forests, and lakes. Easy rules, clever scoring, a modern classic."}, "Pikomino": {"fr": "Un jeu de dés gourmand où l'on chipe des brochettes de vers à ses adversaires. Faut-il pousser sa chance ou s'arrêter ? Tendu et rigolo.", "en": "A push-your-luck dice game where you grab tasty worm tiles, but rolling too greedily can cost you everything."}, "Super Mega Lucky Box": {"fr": "Un jeu de dés et de grilles où on coche des cases pour déclencher des combos. Hyper simple, hyper fun, et parfait pour jouer à plein!", "en": "Cross off numbers on your grids to score points and unlock bonuses. A super fast roll-and-write where luck and timing are everything."}, "Harvest Dice": {"fr": "Un petit jeu de dés et de feuille à cocher : on cultive son potager en plaçant ses légumes au bon endroit. Court et malin.", "en": "A roll-and-write dice game where you plant carrots, tomatoes, and lettuce in your garden grid. Quick, charming, and easy for all ages."}, "Perfect Word": {"fr": "Un jeu de mots coopératif où l'on essaie de deviner le mot parfait choisi par un joueur à partir de petits indices. Ambiance complice garantie.", "en": "A cooperative word game where teammates give clues to guess a secret word together, perfect for a fun group challenge."}, "Astérix les défis": {"fr": "Une série de mini-défis avec les héros gaulois : adresse, rapidité et malice s'enchaînent pour relever les épreuves d'Astérix et ses amis.", "en": "A challenge game set in the world of Astérix, with mini-games and puzzles to overcome alongside your favorite Gaulish heroes."}, "Comment j'ai adopté un gnou": {"fr": "Jeu d'ambiance complètement loufoque où l'on raconte des histoires improbables à partir de mots tirés au hasard. Hilarant en famille.", "en": "Tell silly stories and pick the funniest answers about adopting wild animals. A goofy family game full of laughs."}, "Timeline": {"fr": "Un jeu de cartes culture générale: il faut placer les événements dans le bon ordre sur la frise. On apprend plein de choses en s'amusant!", "en": "Place cards on a growing line in the right historical order. A neat little game that teaches you fun facts while you play."}, "Sushi Roll": {"fr": "La version dés de Sushi Go! On lance, on garde, on passe son plateau-tapis roulant et on attrape les meilleurs sushis. Gourmand et malin!", "en": "The dice version of Sushi Go! Roll, pick and pass conveyor belts of sushi dice to collect the tastiest combos."}, "Crack List": {"fr": "Jeu d'ambiance survolté où il faut citer des mots d'une catégorie à toute vitesse. Cris, rires et neurones en ébullition garantis.", "en": "Two teams shout out words on a theme, eliminating letters as they go. Fast, fun, and a real brain-warmer!"}, "Corinth": {"fr": "Jeu de dés à l'antique : on lance, on choisit ses dés et on construit sa cité grecque pour marquer le plus de points. Malin et rapide.", "en": "Roll dice and pick groups to build up your ancient city. A quick, clever drafting game with satisfying choices each turn."}, "Imagine": {"fr": "Avec des cartes transparentes, on mime des mots en les superposant et bougeant. Un jeu d'ambiance et de créativité super original.", "en": "A creative party game where you use transparent cards to mime concepts for others to guess. Surprisingly clever and full of laughs."}, "Mr Jack Pocket": {"fr": "Duel malin pour deux joueurs : l'un cache Mr Jack, l'autre le démasque en faisant tourner les tuiles. Court, intense et plein de déductions !", "en": "A tiny two-player deduction game where one of you hunts Jack the Ripper through London while the other helps him escape. Quick, sneaky, and clever!"}, "Affabul": {"fr": "Un jeu d'ambiance où l'on invente des histoires farfelues à partir d'images ou de mots. Les fous rires sont garantis.", "en": "A storytelling card game where players invent wild tales together, building silly or surprising stories one card at a time."}, "Sequence": {"fr": "Mélange de cartes et de plateau : posez vos jetons pour aligner cinq pions à la suite. Un jeu de stratégie simple qui plaît à toute la famille.", "en": "Play cards from your hand to claim spots on the board and line up five chips in a row. A simple mix of cards and strategy for the whole family."}, "Seven Wonders Architects": {"fr": "Construisez votre merveille en piochant des cartes tour à tour. Version simplifiée et fluide de 7 Wonders, parfaite pour démarrer en stratégie.", "en": "Build your own ancient Wonder card by card in this easier, faster version of 7 Wonders. Great for kids stepping into civilization games!"}, "Jeu des cochons": {"fr": "Un grand classique de dés rigolos : on lance deux petits cochons et selon leur position, on marque des points… ou on perd tout !", "en": "The classic Pass the Pigs dice game, but with tiny pig figures instead of dice. Roll, push your luck, and score by how they land."}, "Dominion": {"fr": "Le grand classique du deck-building: chacun construit son propre paquet de cartes au fil de la partie pour bâtir son royaume. Stratégique et infiniment rejouable.", "en": "Build your own deck of cards turn after turn to buy victory points. The classic deck-builder that started it all."}, "Onitama": {"fr": "Un duel stratégique inspiré des arts martiaux : déplacez vos pions selon des cartes de mouvements pour capturer le maître adverse. Vif et élégant.", "en": "A two-player martial arts duel on a tiny board, where the moves you can make change every turn based on shared kung-fu cards."}, "Splendor Duel": {"fr": "La version en duel du célèbre Splendor: on collecte des gemmes et des cartes pour devenir le marchand le plus prestigieux. Un face-à-face stratégique et élégant.", "en": "A head-to-head version of Splendor for two players. Collect sparkling gems and buy cards to be the first to reach the winning goals."}, "Take 12": {"fr": "Un petit jeu de cartes rapide où il faut être malin pour ne pas se retrouver coincé avec la carte 12. Parfait pour jouer en famille.", "en": "Roll, pick, and push your luck to grab the best combos. A quick dice game where bold choices pay off, but greed can cost you."}, "Harry Potter: Défense contre les forces du mal": {"fr": "Un duel de sorciers à coups de cartes de sorts inspiré d'Harry Potter. On attaque, on se défend et on essaie d'éliminer son adversaire.", "en": "A two-player Harry Potter dueling card game. Cast spells, dodge curses, and outwit your opponent in magical face-offs."}, "Papayoo": {"fr": "Un jeu de cartes façon levées où il faut éviter de ramasser les pique… et surtout le redouté 7 de Papayoo qui plombe le score !", "en": "A fast trick-taking card game where you want to avoid winning the dreaded Papayoo cards, full of twists for the whole family."}, "Harmonies": {"fr": "On compose des paysages en plaçant joliment des petits jetons colorés et en faisant nicher des animaux. Un jeu doux, créatif et très beau.", "en": "A peaceful tile-placement game where you build little landscapes and attract animals. Beautiful, relaxing, and great for the whole family."}, "Paw!": {"fr": "Un jeu de cartes rapide où il faut être le plus rapide à attraper la bonne carte avec la patte. Parfait pour rigoler en famille.", "en": "A quick card game where you slap your paw down at just the right moment. Fast, silly, and full of laughs for 2 to 6 players."}, "Draw Hotel": {"fr": "Un roll-and-write où l'on dessine et aménage son hôtel pour attirer les clients. Simple à comprendre et très satisfaisant à remplir!", "en": "Roll dice and draw your own hotel floor by floor. A cute roll-and-write where you design the fanciest building in town."}, "Palm Island": {"fr": "Un jeu solo ou à deux qui tient dans la main : on fait tourner un paquet de cartes pour développer sa petite île tropicale.", "en": "A clever solo or 2-player card game played entirely in your hands, no table needed. Build your island village while traveling or queuing."}, "Wazabi": {"fr": "Un jeu de dés explosif où il faut se débarrasser de tous ses dés en premier. Rapide, bruyant et tordant, parfait pour rigoler en famille.", "en": "Toss dice fast and shout 'Wazabi!' to pass them to other players. A noisy, hilarious party game that ends in seconds."}, "Origami": {"fr": "Un petit jeu de cartes malin où l'on plie sa stratégie comme une feuille de papier : collectez et combinez vos cartes pour marquer un maximum de points.", "en": "A quick card game about folding paper creations, drafting and stacking cards to build the prettiest origami collection."}, "Rugby 15": {"en": "A sports board game that recreates the excitement of a rugby match, with strategy and a bit of luck to score tries.", "fr": "Un jeu de plateau de rugby où l'on enchaîne les phases de jeu avec un brin de tactique et un peu de chance pour marquer des essais."}, "Mysterium Park": {"fr": "Un fantôme envoie des visions étranges aux joueurs pour les aider à résoudre un mystère dans une fête foraine. Jeu coopératif rempli d'images poétiques.", "en": "A spooky cooperative game where a silent ghost sends dreamlike picture cards to help the others solve a creepy carnival mystery before time runs out."}, "Beewizz": {"fr": "Jeu de mots rapide où il faut deviner des mots à partir d'indices, mais en moins de syllabes que les autres ! Tendu et rigolo.", "en": "Race to summarize a topic in fewer and fewer words. A buzzing party game where being concise scores big."}, "Lucky Numbers": {"fr": "Remplissez votre grille avec des tuiles numérotées en ordre croissant. Un petit jeu de chance et de réflexion très accessible, parfait en famille.", "en": "Fill your little grid so numbers go up across rows and columns. A relaxing tile-flipping game where being first is the goal."}, "Silver & Gold": {"fr": "Cochez des cases sur des cartes trésor pour compléter vos îles le plus vite possible. Un petit jeu de type flip-and-write très rapide et fun.", "en": "Flip a card, grab a marker, and check off shapes on your treasure maps. A breezy flip-and-fill game that's quick to learn and fun for everyone."}, "Pitchout": {"fr": "Un jeu d'adresse en équipes : les Citoyens affrontent les Hoods en faisant glisser leurs pions sur le plateau pour écraser l'adversaire. Tactique, nerveux et un peu chaotique.", "en": "A team-based dexterity game where you flick your pieces across the board to crush rival squads. Tactical, snappy, and a little chaotic."}};

function slugify(s) {
  return s.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}
function tierOf(r) {
  if (r == null) return 'unrated';
  if (r >= 18) return 'excellent';
  if (r >= 16) return 'great';
  if (r >= 14) return 'good';
  if (r >= 12) return 'okay';
  return 'meh';
}
function isDuo(g) { return /duel|duo|tea for 2|onitama|kodachi/i.test(g.name); }
function is3plus(g) { return g.remarks && /3j|4j/i.test(g.remarks); }
function stars(r) {
  if (r == null) return '<span class="empty">★★★★★</span>';
  const n = Math.round(r / 4);
  return '★'.repeat(n) + '<span class="empty">' + '★'.repeat(5 - n) + '</span>';
}
function norm(s) { return s.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, ''); }

const MAPPING_KEY = 'paulsBoardGames.mapping.v1';
function loadMapping() {
  try {
    const stored = localStorage.getItem(MAPPING_KEY);
    if (stored) return JSON.parse(stored);
  } catch (e) {}
  return JSON.parse(JSON.stringify(DEFAULT_MAPPING));
}
function saveMapping(m) { localStorage.setItem(MAPPING_KEY, JSON.stringify(m)); }
function imagesForGame(slug) { const m = loadMapping(); return m[slug] || []; }
function gameForImage(filename) {
  const m = loadMapping();
  for (const [slug, list] of Object.entries(m)) if (list.includes(filename)) return slug;
  return null;
}
function setImageGame(filename, slug) {
  const m = loadMapping();
  for (const k of Object.keys(m)) {
    m[k] = (m[k] || []).filter(f => f !== filename);
    if (m[k].length === 0) delete m[k];
  }
  if (slug) {
    if (!m[slug]) m[slug] = [];
    if (!m[slug].includes(filename)) m[slug].push(filename);
  }
  saveMapping(m);
}
function findGameBySlug(slug) { return GAMES.find(function(g){ return slugify(g.name) === slug; }); }
function descriptionFor(name, lang) {
  const entry = DESCRIPTIONS[name];
  if (!entry) return null;
  return entry[lang] || entry.fr || entry.en || null;
}
function taggedCount() {
  const m = loadMapping();
  let n = 0;
  for (const k of Object.keys(m)) n += (m[k] || []).length;
  return n;
}
